import json, requests, sys

webhook_url = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

# 构建蓝色卡片消息
card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "🔔 澳洲冰箱新品巡检 - 2026-06-16 上午"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**巡检时间:** 2026年6月16日 10:23 GMT+8\n\n---\n\n## 🏪 海信 Hisense\n✅ **无变化** — 第1页12款产品均在基线中，Release Year 2026 共5款\n\n---\n\n## 🛒 美的 Midea\n⚠️ **2款产品状态变更**\n\n**MDRS925FIM45AP** — Side by Side (Space Master) 700L\n- 基线状态: 在售 → 当前: **Coming Soon** 🔄\n\n**MDRF923FIM45AP** — Quad Door (Space Master) 706L  \n- 基线状态: 在售 → 当前: **Coming Soon** 🔄\n\n📌 **MDRT580MTF45AP** (413L) 仍为 Coming Soon，未变化\n\n---\n\n## 🏭 三星 Samsung\n⚪ 搜索结果未发现新款冰箱信息\n\n## 🏭 LG\n⚪ 搜索结果未发现新款冰箱信息\n\n## 🏠 西屋 Westinghouse  \n⚪ 首次获取产品列表页数据，无基线对比（75款在售）"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动巡检"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook_url, json=card, timeout=10)
result = {"status_code": resp.status_code, "response": resp.text}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

